sys_script_include.script:
var CaseTaskDescriptionBuilder = Class.create();
CaseTaskDescriptionBuilder.prototype = {
    initialize: function() {},

    CONFIG_PROPERTY: 'x_gegis_ins_policy.case_task_type_config',
    TOKEN_PATTERN: /\{([a-zA-Z0-9_]+)\}/g,

    /**
     * @param taskGr GlideRecord x_gegis_ins_policy_case_task, not yet inserted/updated
     */
    apply: function(taskGr) {
        var config = this._getConfig(taskGr.getValue('u_type'));
        if (!config)
            return;

        var tokens = this._buildTokens(taskGr);

        if (!taskGr.getValue('short_description') && config.desc_template)
            taskGr.setValue('short_description', this._resolve(config.desc_template, tokens));

        if (!taskGr.getValue('priority') && config.priority)
            taskGr.setValue('priority', config.priority);

        if (!taskGr.getValue('due_date') && config.due_hours) {
            var due = new GlideDateTime();
            due.addSeconds(parseFloat(config.due_hours) * 3600);
            taskGr.setValue('due_date', due);
        }

        if (!taskGr.getValue('assignment_group') && config.assignment_group) {
            var group = this._lookupGroup(config.assignment_group);
            if (group)
                taskGr.setValue('assignment_group', group);
        }

        if (!taskGr.getValue('assigned_to') && config.assigned_to) {
            var user = this._lookupUser(config.assigned_to);
            if (user)
                taskGr.setValue('assigned_to', user);
        }
    },

    _getConfig: function(uType) {
        var raw = gs.getProperty(this.CONFIG_PROPERTY, '{}');
        var map;
        try {
            map = JSON.parse(raw);
        } catch (e) {
            gs.error('CaseTaskDescriptionBuilder: malformed JSON in property ' + this.CONFIG_PROPERTY + ' - ' + e.message);
            return null;
        }
        return (uType && map[uType]) || map['default'] || null;
    },

    _buildTokens: function(taskGr) {
        var tokens = {
            lob: '',
            insured: '',
            broker: '',
            tiv: '',
            submission_number: ''
        };

        var subId = taskGr.getValue('submission');
        if (!subId)
            return tokens;

        var sub = new GlideRecord('x_gegis_ins_policy_submission');
        if (!sub.get(subId))
            return tokens;

        tokens.submission_number = sub.getValue('number') || '';
        tokens.insured = sub.getValue('insured_name') || sub.getDisplayValue('primary_insured') || '';
        tokens.broker = sub.getValue('broker_name') || sub.getDisplayValue('broker') || '';
        tokens.lob = sub.getDisplayValue('line_of_business') || '';
        tokens.tiv = this._sumInsuredValue(subId);

        return tokens;
    },

    _sumInsuredValue: function(subId) {
        var ga = new GlideAggregate('x_gegis_ins_policy_submission_line');
        ga.addQuery('submission', subId);
        ga.addAggregate('SUM', 'total_insured_value');
        ga.query();
        if (ga.next()) {
            var sum = ga.getAggregate('SUM', 'total_insured_value');
            if (sum)
                return parseFloat(sum).toLocaleString('en-US');
        }
        return '';
    },

    // leftover tokens (no submission, missing field) resolve to '' - trims the
    // orphaned ", " / ". " that would otherwise remain in the sentence.
    _resolve: function(template, tokens) {
        var text = template.replace(this.TOKEN_PATTERN, function(match, key) {
            var value = tokens[key];
            return value ? value : '';
        });
        return text.replace(/\(\s*\)/g, '').replace(/\s{2,}/g, ' ').replace(/\s+([,.])/g, '$1').replace(/^[,.\s]+/, '').trim();
    },

    _lookupGroup: function(name) {
        var gr = new GlideRecord('sys_user_group');
        gr.addQuery('name', name);
        gr.setLimit(1);
        gr.query();
        return gr.next() ? gr.getUniqueValue() : '';
    },

    _lookupUser: function(userName) {
        var gr = new GlideRecord('sys_user');
        gr.addQuery('user_name', userName);
        gr.setLimit(1);
        gr.query();
        return gr.next() ? gr.getUniqueValue() : '';
    },

    type: 'CaseTaskDescriptionBuilder'
};
